class Counter {
    private int count;

    public synchronized int get() {
        return count;
    }

    public void increment() {
        count = count + 1;
    }
}

AtomicInteger count = new AtomicInteger(0);

// each of 1000 threads runs once:
count.incrementAndGet();

// after every thread has finished:
System.out.println(count.get());

class Stats {
    volatile int handled = 0;   // shared between threads
}

Stats s = new Stats();
Runnable task = () -> {
    int local = 0;
    for (int i = 0; i < 1000; i++) {
        local = local + 1;
        s.handled = s.handled + 1;
    }
};
// two threads run task and both finish, then:
System.out.println(s.handled);

