class RequestCounter {
    private volatile int count;

    public void record() {
        count = count + 1;
    }

    public int total() {
        return count;
    }
}

AtomicInteger shared = new AtomicInteger(0);

Runnable task = () -> {
    int local = 0;
    for (int i = 0; i < 500; i++) {
        local = local + 1;
        shared.incrementAndGet();
    }
};
// four threads run task and all finish, then:
System.out.println(shared.get());
